action.command:
python3 -c "import struct; import os; import base64; files = sorted([f for f in os.listdir('.') if f.startswith('block_') and not f.startswith('block_garbage')]); data = b''; block_data = [];
for f in files:
    with open(f, 'rb') as bf:
        raw = bf.read();
        seq_num = struct.unpack('<I', raw[:4])[0];
        block_data.append((seq_num, raw[4:]));
block_data.sort(key=lambda x: x[0]);
for seq, block in block_data:
    data += block;
credentials_section = data[data.find(b'[credentials]'):data.find(b'[backup]')]
keys = []
for line in credentials_section.decode('utf-8', errors='ignore').split('\n'):
    if line.startswith('ENCRYPTED_KEY='):
        keys.append(line.split('=', 1)[1])

